static void select(Host&h,int slot){auto&p=*h.p;if(slot>=14){p.set(kCymbalView,1);p.set(kSoundRow,slot-14);}else if(slot>=8){p.set(kSoundPart,(slot-8)/3);p.set(kSoundRow,(slot-8)%3+1);}else{p.set(kSoundPart,slot<2?slot:slot<4?2:3);p.set(kSoundRow,slot<2?0:slot<4?slot-2:slot-4);}assert(p.soundReverseSlot(p.getInt(kSoundRow))==slot);}
static auto oldState(const std::vector<uint8_t>&state){std::vector<uint8_t>out(state.begin(),state.begin()+12);for(int n=0;n<4;++n)out[8+n]=uint8_t(643>>(n*8));size_t pos=12;for(int i=0;i<kParamCount;++i){size_t bytes=1+state[pos]+8;if(i<643)out.insert(out.end(),state.begin()+pos,state.begin()+pos+bytes);pos+=bytes;}uint32_t size=0;for(int n=0;n<4;++n)size|=uint32_t(state[pos+n])<<(8*n);size-=G::ReverseTrailerSize;for(int n=0;n<4;++n)out.push_back(uint8_t(size>>(8*n)));out.insert(out.end(),state.begin()+pos+4,state.begin()+pos+4+size);return out;}
