 {Host h;auto&p=*h.p;for(int slot=0;slot<17;++slot){select(h,slot);int row=p.getInt(kSoundRow);p.set(kSoundTune0+row,-11+slot);p.syncLayerUi();if(std::abs(p.get(p.soundKey(row,G::LTune))-(-11+slot))>.001f||std::abs(p.get(kSoundTune0+row)-(-11+slot))>.001f){std::cerr<<"Tune slot="<<slot<<" target="<<p.soundKey(row,G::LTune)<<" actual="<<p.get(p.soundKey(row,G::LTune))<<" relay="<<p.get(kSoundTune0+row)<<"\n";std::abort();}assert(p.soundTarget(row*4+2)==p.soundKey(row,G::LTune));}p.set(kSoundPart,2);p.set(kSoundTune3,9);assert(p.get(kSoundTune3)==0);h.render();auto state=p.internalSaveState();Host copy;assert(copy.p->internalLoadState(state.data(),state.size()));copy.render();if(copy.p->internalSaveState()!=state){for(int k=0;k<kParamCount;++k)if(p.getNormalised(k)!=copy.p->getNormalised(k))std::cerr<<p.param(k).id<<" before="<<p.get(k)<<" after="<<copy.p->get(k)<<"\n";std::abort();}std::cout<<"PASS direct per-row Tune for17sounds, detail isolation, Tune Q-Link and exact state restore\n";}

 {Host h;auto&p=*h.p;assert(kReverse0==643&&kSoundRev0==660&&kParamCount==779);for(int slot=0;slot<17;++slot){select(h,slot);int row=p.getInt(kSoundRow);p.set(kSoundRev0+row,1);assert(p.getBool(kReverse0+slot));p.syncLayerUi();assert(p.getBool(kSoundRev0+row));for(int other=0;other<17;++other)assert(p.getBool(kReverse0+other)==(other<=slot));}p.set(kSoundPart,2);p.set(kSoundRev3,1);assert(!p.getBool(kSoundRev3));for(int n=0;n<17;++n)assert(p.getBool(kReverse0+n));
 p.set(kUserKit,3);h.pulse(kSaveKit);for(int n=0;n<17;++n)p.set(kReverse0+n,0);h.pulse(kLoadKit);for(int n=0;n<17;++n)assert(p.getBool(kReverse0+n));auto state=p.internalSaveState();Host copy;assert(copy.p->internalLoadState(state.data(),state.size()));for(int n=0;n<17;++n)assert(copy.p->getBool(kReverse0+n)&&copy.p->savedReverse[3][n].load());copy.render();assert(copy.p->internalSaveState()==state);auto old=oldState(state);assert(copy.p->internalLoadState(old.data(),old.size()));for(int n=0;n<17;++n)assert(!copy.p->getBool(kReverse0+n)&&!copy.p->savedReverse[3][n].load());std::cout<<"PASS17independent REV relays, hat-detail isolation, user kit, exact state roundtrip and old643state defaults\n";}
 // Stereo interpolation runs backward from the source end; Start trims from that end.
 for(double rate:{44100.,48000.,96000.})for(int block:{31,128,511})for(int slot=0;slot<17;++slot){Host h;h.rate=rate;h.block=block;h.impulse();auto&p=*h.p;select(h,slot);int row=p.getInt(kSoundRow);dsp::WavData*s=nullptr;
  if(slot>=14){p.set(kCym0Sample+(slot-14)*G::LayerFields,-1);s=&p.cymbalFallback[slot-14];}
  else if(slot>=8){int role=(slot-8)/3,layer=(slot-8)%3+1;h.pin(role,layer);s=&p.library.slots[8+slot-8].sound;}
  else{p.set(kXSample0+slot,0);p.set(kSample0+slot*9,0);s=&p.sounds[slot*8];}
  s->sampleRate=44100;s->channels.assign(2,std::vector<float>(10000));for(int n=0;n<10000;++n){s->channels[0][n]=.01f+.2f*n/9999;s->channels[1][n]=-.03f-.1f*n/9999;}
  p.set(p.soundKey(row,G::LTune),7);p.set(p.soundKey(row,G::LStart),2);p.set(p.soundKey(row,G::LShift),-30);p.set(kSoundRev0+row,1);p.triggerLayers(-1,100,100); // invalid roles stay safe
  if(slot>=14)p.triggerCymbal(slot-14,100,500,true);else p.triggerLayers(p.soundRole(row),100,500,p.soundLayer(row),true);
  G::Voice*v=nullptr;for(auto&voice:p.voices)if(voice.active){assert(!v);v=&voice;}assert(v&&v->step<0&&std::abs(v->pos-(9999-88.2))<1.e-6);double start=v->pos,step=v->step;h.render();if(v->active)assert(std::abs(v->pos-(start+step*block))<1.e-5);double energy=0;for(int frame=0;frame<block;++frame){assert(std::isfinite(h.data[0][frame])&&std::isfinite(h.data[1][frame]));energy+=std::abs(h.data[0][frame])+std::abs(h.data[1][frame]);}assert(energy>.001);for(int i=0;i<int(10000/std::abs(step)/block)+3;++i)h.render();for(auto&voice:p.voices)assert(!voice.active);
 }
 std::cout<<"PASS17reverse sounds x3rates x3blocks: stereo resampling, signed direction, Start from end, finite termination and process allocation guard\n";
